-- Delve: a small roguelike for XTOS Licorice, API 2.0 (uses tools/gamekit).
--
-- Ten depths of rooms and corridors, a new dungeon every run (or today's dungeon, the same for
-- everyone on a day). Find the stairs down; on depth 10 a dragon guards the amulet. A depth is
-- 15 x 19 tiles; the screen shows 10 x 12 of them at 48 px (a fingertip), pictures from
-- sprites.lua (16 x 16 pixel art drawn at 3x), and the view moves half a screen when the hero
-- comes near its edge.
--
-- Turn-based: each step or blow is a turn, and the monsters move after it. A tap within two tiles
-- of the hero steps that way (one of eight directions, so it need not hit the tile): it opens a
-- door or hits a monster there. A tap further away walks there (it stops when a monster comes
-- into view); a tap on the hero waits, or goes down on the stairs. Tap a monster further away, or
-- hold one, to see what a fight would cost.
--
-- The torch is the clock: it burns one a turn and lights 5 tiles around the hero, 3 once it runs
-- low, 1 when it is out (and with no light, no healing). Torches lie about. Potions and scrolls are
-- unknown until tried (their colours and labels change every run). Death ends the run.
--
-- The map's still part (walls, doors, items) is drawn into an off-screen layer after each turn, in
-- calls of at most LAYER_BUDGET commands (the reader drops what one call draws past about 1024);
-- each frame draws the layer back, the monsters and the hero over it, then the status lines and
-- buttons. Nothing large is filled black: big black areas ghost on e-ink.

local SP = require('sprites')

local W, H = kit.W, kit.H
local COLS, ROWS = 15, 19          -- a depth, in tiles
local T, ART = 48, 3               -- a tile on screen; screen pixels a picture pixel
local VCOLS, VROWS = 10, 12        -- the view, in tiles
local MAP_Y = 56
local MAP_H = VROWS * T
local MSG_Y = MAP_Y + MAP_H + 6
local BTN_Y, BTN_H = 726, 62
local LAST_DEPTH = 10
local TORCH_MAX, TORCH_START = 600, 300
local BAG_MAX = 12
local LAYER_BUDGET = 600         -- drawing commands a layer:draw call (the reader drops past ~1024)
local ROCK, FLOOR, DOOR, OPEN, STAIRS = 0, 1, 2, 3, 4

-- patience: turns a monster follows the hero's trail out of sight before it gives up and wanders;
-- coward: runs off when down to a third of its HP; ignore: % chance it notices the hero and does not
-- care; guard: does not wander
local MONSTERS = {
  rat      = { name = 'rat', hp = 4, lo = 1, hi = 3, def = 0, xp = 2, from = 1, to = 3, patience = 3, ignore = 30, coward = true,
               note = 'Soon loses interest; runs off when hurt.' },
  bat      = { name = 'bat', hp = 3, lo = 1, hi = 2, def = 0, xp = 2, from = 1, to = 4, patience = 2, ignore = 30, erratic = true,
               note = 'Flits about at random.' },
  snake    = { name = 'snake', hp = 7, lo = 2, hi = 4, def = 1, xp = 4, from = 2, to = 5, patience = 5, ignore = 20 },
  goblin   = { name = 'goblin', hp = 9, lo = 2, hi = 4, def = 1, xp = 6, from = 3, to = 6, patience = 6, ignore = 10, thief = true,
               coward = true, note = 'Steals gold, then runs off. Flees when hurt.' },
  skeleton = { name = 'skeleton', hp = 14, lo = 3, hi = 6, def = 2, xp = 9, from = 4, to = 8, patience = 15,
               note = 'Never tires of the chase.' },
  orc      = { name = 'orc', hp = 18, lo = 4, hi = 7, def = 3, xp = 13, from = 5, to = 9, patience = 7 },
  troll    = { name = 'troll', hp = 28, lo = 5, hi = 9, def = 3, xp = 20, from = 7, to = 10, patience = 6, regen = true,
               note = 'Heals a little every turn.' },
  wraith   = { name = 'wraith', hp = 20, lo = 4, hi = 8, def = 4, xp = 24, from = 8, to = 10, patience = 20, dark = true,
               note = 'Its touch eats your torch. It does not give up.' },
  dragon   = { name = 'dragon', hp = 60, lo = 7, hi = 12, def = 5, xp = 50, from = 99, to = 99, patience = 3, guard = true,
               note = 'Guards the amulet.' },
}
